package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import java.util.concurrent.*;
/** Explicit opt-in; previews and Save never alter the user's alarm or guard schedule. */
public final class SmartBedtimeActivity extends Activity {
 private SleepPlan draft;private SmartBedtimeRuntime.Snapshot preview;private String error="",token,deliveryStatus="";private boolean resumed,reading;private Dialog repeatPicker;private int generation;private final ExecutorService reader=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);try{draft=SleepPlans.load(this);if(state!=null){draft.smartBedtime=state.getBoolean("smart");draft.noAlarmBedtime=state.getBoolean("fallback");draft.smartRepeatMinutes=state.getInt("repeatMinutes",draft.smartRepeatMinutes);draft.smartRepeatLimit=state.getInt("repeatLimit",draft.smartRepeatLimit);draft.revision=state.getLong("revision");token=state.getString("token");error=state.getString("error","");}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();}catch(RuntimeException failure){error="Saved plan needs attention. Reopen Sleep goals.";render();}}
 @Override protected void onResume(){super.onResume();resumed=true;if(draft!=null){load();observeSave();watch.run();}}
 private void load(){reading=true;int request=++generation;SleepPlan copy=draft.copy();render();reader.execute(()->{try{SmartBedtimeRuntime.Snapshot value=SmartBedtimeRuntime.preview(getApplicationContext(),copy);runOnUiThread(()->{if(isDestroyed()||request!=generation)return;reading=false;preview=value;render();});}catch(RuntimeException failure){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;reading=false;error="Preview unavailable: "+(failure.getMessage()==null?"saved history needs attention":failure.getMessage());render();});}});}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Smart Bedtime",this::finish);Design.space(body,14);if(draft==null){Design.text(body,error,15,500,Design.BROWN);return;}Design.toggle(body,"Use Smart Bedtime","Reminder follows the next actual alarm",draft.smartBedtime,on->{draft.smartBedtime=on;render();load();}).setEnabled(token==null);Design.space(body,12);Design.toggle(body,"Fixed bedtime without an alarm","Use the saved fixed reminder only when no eligible alarm exists",draft.noAlarmBedtime,on->{draft.noAlarmBedtime=on;render();load();}).setEnabled(token==null);Design.space(body,12);PlanActivity.detail(body,"clock","Repeat reminders","Silent notifications until tracking or dismissal",draft.smartRepeatMinutes==0?"Off":draft.smartRepeatMinutes+" min",this::repeatInterval);if(draft.smartRepeatMinutes>0)PlanActivity.detail(body,"bell","Additional repeat limit","Stops before the wake-up alarm and within 2 h",String.valueOf(draft.smartRepeatLimit),this::repeatLimit);Design.space(body,16);Design.text(body,"Saved goal · "+PlanActivity.duration(draft.goal),17,600,Design.INK);Design.text(body,"Reminder advance · "+draft.reminderAdvance+" min",13,400,Design.MUTED);Design.space(body,14);
  if(reading)Design.text(body,"Calculating from saved records…",13,400,Design.MUTED);if(preview!=null){SmartBedtime.Result r=preview.result;String next=r.at<=0?"No eligible reminder":format(r.at);PlanActivity.detail(body,"bell","Calculated reminder",r.fallback?"Explicit fixed fallback":r.at<=0?r.issue:"Based on alarm #"+r.alarmId,next,null).setContentDescription("Smart bedtime preview "+next);if(r.alarmAt>0)PlanActivity.detail(body,"alarm","Next actual alarm",null,format(r.alarmAt),null);PlanActivity.detail(body,"moon","Recorded coverage",r.observed+" of 5 recent days observed",r.observed==0?"Unknown":Math.max(0,r.shortfall/60000)+" min short",null);PlanActivity.detail(body,"clock","Earlier adjustment","Recorded shortfall above 10 min · capped at 45 min",r.adjustment+" min",null);Design.text(body,"Smart window "+r.smart+" min · tracking delay "+r.delay+" min",13,400,Design.MUTED);if(!preview.access.isEmpty())Design.text(body,preview.access,13,500,Design.BROWN).setContentDescription("Smart bedtime access error");if(preview.tracking)Design.text(body,"Reminder is suppressed while tracking.",13,500,Design.BROWN);if(r.at>0&&r.at<=SmartBedtimeRuntime.clock.getAsLong())Design.text(body,"Initial calculated time has passed. An active repeat series keeps its own schedule.",13,500,Design.BROWN);}
  Design.space(body,12);Design.text(body,"Missing nights stay unknown. Adjustment compares recorded duration with the current goal; it is not a sleep-debt diagnosis. Your saved bedtime, guard and wake-up alarms stay unchanged.",12,400,Design.MUTED);PlanActivity.detail(body,"shield","Reminder access","Notifications and Alarms & reminders",null,()->{try{startActivity(new Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,android.net.Uri.parse("package:"+getPackageName())));}catch(RuntimeException denied){error="Open Android Settings → SleepWell → Alarms & reminders.";render();}});PlanActivity.detail(body,"bell","Notification settings",null,null,()->{try{startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));}catch(RuntimeException denied){error="Open Android Settings → SleepWell → Notifications.";render();}});
  android.content.SharedPreferences receipt=SmartBedtimeRuntime.journal.open(this);long scheduled=receipt.getLong("at",0);if(!receipt.getString("nonce","").isEmpty()&&scheduled>SmartBedtimeRuntime.clock.getAsLong())PlanActivity.detail(body,"bell","Next scheduled reminder",receipt.getBoolean("repeatStep",false)?"Silent repeat":"Initial reminder",format(scheduled),null);String ownedSeries=receipt.getString("series","");if(!ownedSeries.isEmpty())Design.button(body,"Dismiss tonight’s reminders",false,()->SmartBedtimeRuntime.dismiss(this,ownedSeries,()->main.post(()->{if(!isDestroyed())render();})));Design.text(body,"Repeats are silent. Android may delay them. Tracking, dismissal, restart or a clock change ends the current series.",12,400,Design.MUTED);
  LinearLayout footer=RecordUi.footer(body);if(!deliveryStatus.isEmpty())Design.text(footer,deliveryStatus,12,500,Design.BROWN).setContentDescription("Smart bedtime delivery status "+deliveryStatus);if(!error.isEmpty())Design.text(footer,error,13,500,Design.BROWN).setContentDescription("Smart bedtime status");Design.text(footer,draft.smartBedtime?"Save enables bedtime reminders. Fixed reminders remain available when Smart Bedtime is off.":"Off keeps the existing fixed reminder preference.",12,400,Design.MUTED);Button save=Design.button(footer,token==null?"Save Smart Bedtime":"Saving…",true,this::save);save.setEnabled(token==null);Button refresh=Design.button(footer,"Refresh preview",false,()->{error="";load();});refresh.setEnabled(token==null&&!reading);}
 private String format(long time){return Instant.ofEpochMilli(time).atZone(SmartBedtimeRuntime.zone.get()).format(DateTimeFormatter.ofPattern("EEE d MMM · HH:mm",Locale.getDefault()));}
 private void repeatInterval(){if(token!=null)return;if(repeatPicker!=null)repeatPicker.dismiss();int[] values={0,5,10,15,30,60};String[] labels={"Off","Every 5 min","Every 10 min","Every 15 min","Every 30 min","Every 60 min"};int selected=0;for(int n=0;n<values.length;n++)if(values[n]==draft.smartRepeatMinutes)selected=n;repeatPicker=SleepPicker.choices(this,"Repeat bedtime reminders",labels,selected,n->{draft.smartRepeatMinutes=values[n];render();load();});}
 private void repeatLimit(){if(token!=null)return;if(repeatPicker!=null)repeatPicker.dismiss();int[] values={1,3,6,12};String[] labels={"1 additional reminder","3 additional reminders","6 additional reminders","12 additional reminders"};int selected=1;for(int n=0;n<values.length;n++)if(values[n]==draft.smartRepeatLimit)selected=n;repeatPicker=SleepPicker.choices(this,"Additional reminder limit",labels,selected,n->{draft.smartRepeatLimit=values[n];render();load();});}
 private void save(){if(token!=null)return;token=UUID.randomUUID().toString();observeSave();render();}
 private void observeSave(){if(!resumed||token==null)return;SleepPlan copy=draft.copy();if(copy.smartBedtime)copy.reminder=true;SleepPlans.Repository repository=SleepPlans.repository(this);SleepPlans.Reminder schedule=SleepPlans.reminders;PlanOperations.Operation operation=PlanOperations.start(this,token,app->{repository.save(copy);schedule.apply(app);return null;});if(!operation.done){main.removeCallbacks(poll);main.postDelayed(poll,100);return;}PlanOperations.forget(token);token=null;if(operation.error!=null)error="Could not finish saving: "+operation.error;else{draft=repository.load();error="Smart Bedtime saved. Reminder will be recalculated.";}render();load();}
 private final Runnable watch=new Runnable(){public void run(){if(!resumed)return;String status=SmartBedtimeRuntime.journal.open(SmartBedtimeActivity.this).getString("status","");if(!status.equals(deliveryStatus)){deliveryStatus=status;render();}main.postDelayed(this,250);}};private final Runnable poll=this::observeSave;@Override protected void onPause(){resumed=false;main.removeCallbacks(poll);main.removeCallbacks(watch);super.onPause();}@Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(draft!=null){state.putBoolean("smart",draft.smartBedtime);state.putBoolean("fallback",draft.noAlarmBedtime);state.putInt("repeatMinutes",draft.smartRepeatMinutes);state.putInt("repeatLimit",draft.smartRepeatLimit);state.putLong("revision",draft.revision);state.putString("token",token);state.putString("error",error);}}
 void awaitReaders(long timeout)throws Exception{if(reader.isShutdown()){if(!reader.awaitTermination(timeout,TimeUnit.MILLISECONDS))throw new TimeoutException("Bedtime preview busy");}else reader.submit(()->{}).get(timeout,TimeUnit.MILLISECONDS);}
 @Override protected void onDestroy(){generation++;if(repeatPicker!=null)repeatPicker.dismiss();main.removeCallbacks(poll);main.removeCallbacks(watch);reader.shutdown();super.onDestroy();}@Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
